T_PROTO_DESC_PAYLOAD_STABLE: assert property (@(posedge clk) disable iff (rst)
    (desc_tvalid && !desc_tready) |=>
        $stable({desc_tdata, desc_tkeep, desc_tlast, desc_tid}));

T_RESET_DF_TABLE_IDLE: assert property (@(posedge clk)
